sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var assetCountField = current.isValidField('asset_count') ? 'asset_count' : 'u_asset_count';
    var revokedField = current.isValidField('system_access_revoked') ? 'system_access_revoked' : 'u_system_access_revoked';

    var remainingAssets = parseInt(current.getValue(assetCountField), 10) || 0;
    var isAccessRevoked = current.getValue(revokedField) == '1' || current.getValue(revokedField) == true;

    // Validation checks
    var errorMessages = [];

    if (remainingAssets > 0) {
        errorMessages.push('Cannot close request: Employee still has ' + remainingAssets + ' assigned asset(s) that must be returned.');
    }

    if (!isAccessRevoked) {
        errorMessages.push('Cannot close request: Corporate system access has not been confirmed as revoked.');
    }

    // If validation fails, abort action and notify user
    if (errorMessages.length > 0) {
        for (var i = 0; i < errorMessages.length; i++) {
            gs.addErrorMessage(errorMessages[i]);
        }
        current.setAbortAction(true);
        gs.info('[OffboardingBR] Closure aborted for record ' + current.getValue('number') + ': ' + errorMessages.join(' | '));
    }

})(current, previous);
